; p4test.asm — generated by p4gen.py: the Pentium 4's transcript image (SSE2):
; double precision — every packed and scalar arithmetic instruction over
; eight operand pairs (zeros, denormals, infinities, quiet and signalling
; NaNs, the extremes, random doubles), register and memory forms, again
; under each rounding mode and with flush-to-zero; CMPPD/CMPSD's eight
; predicates, COMISD/UCOMISD, the moves and shuffles, the conversions
; among singles, doubles and integers; the 128-bit integer forms of the
; MMX instructions and SSE2's own (PSHUFD/HW/LW, PSRLDQ/PSLLDQ,
; PUNPCK*QDQ, PADDQ/PSUBQ/PMULUDQ, MOVQ2DQ/MOVDQ2Q, MASKMOVDQU, MOVNTDQ,
; MOVNTI); then by hand: CPUID (the CLFLUSH line), CLFLUSH, LFENCE,
; MFENCE, PAUSE, the MXCSR mask, reserved prefixes. SSE itself is
; p3test.asm's (p3gen.py), not repeated. p3gen.py's frame. Run by
; pgrun.py --mp4 (against Bochs's p4_willamette).
        cpu willamette
        org 0x7C00

STAGE2_LMA  equ 0x7E00
STAGE2_SECS equ 35
IDT_BASE    equ 0x6000
TSS_BASE    equ 0x6800
STACK0      equ 0x7000
STACK3      equ 0x5000
STACK0T     equ 0x6E00
PD          equ 0x10000
PT0         equ 0x11000
PT1         equ 0x12000
SEL_CODE    equ 0x08
SEL_DATA    equ 0x10
SEL_CODE3   equ 0x18 | 3
SEL_DATA3   equ 0x20 | 3
SEL_TSS     equ 0x28
RET_VEC     equ 0x30
TRAP_VEC    equ 0x32                ; a 32-bit trap gate: IF stays as it was
INTR_VEC    equ 0x33                ; a 32-bit interrupt gate: IF cleared
CR4_TSD     equ 0x04
CR4_PSE     equ 0x10
CR4_PGE     equ 0x80
CR4_PCE     equ 0x100

; ---------------------------------------------------------------- stage 1
        bits 16
stage1:
        cli
        cld
        xor ax, ax
        mov ds, ax
        mov es, ax
        mov ss, ax
        mov sp, 0x7C00
        mov ax, 0x0211                  ; 17 sectors: 2-18, head 0
        mov cx, 0x0002
        mov dx, 0x0000
        mov bx, STAGE2_LMA
        int 0x13
        jc  .h
        mov ax, 0x0212                  ; 18: 1-18, head 1
        mov cx, 0x0001
        mov dx, 0x0100
        mov bx, STAGE2_LMA + 17 * 512
        int 0x13
        jc  .h
        jmp stage2
.h:     hlt
        jmp .h
        times 510 - ($ - $$) db 0
        dw 0xAA55

; ---------------------------------------------------------------- stage 2
stage2:
        mov eax, cr0                ; ET as the machine came up
        mov [cr0_boot], eax
        mov al, 0xFF                ; every IRQ masked at the PIC: ring 3 runs with IF
        out 0x21, al                ; set, and a timer tick there reads as vector 8 (a
        out 0xA1, al                ; slow -V run on the host clock took one in T23)
        in al, 0x92                 ; A20 on
        or al, 2
        out 0x92, al
        lgdt [gdtr]
        mov eax, cr0
        or al, 1
        mov cr0, eax
        jmp SEL_CODE:pm32

        bits 32
pm32:
        mov ax, SEL_DATA
        mov ds, ax
        mov es, ax
        mov fs, ax
        mov gs, ax
        mov ss, ax
        mov esp, STACK0
        mov edi, IDT_BASE
        xor ecx, ecx
.idt:   mov eax, fault_stubs
        mov edx, ecx
        shl edx, 3
        add eax, edx
        mov [edi], ax
        mov word [edi+2], SEL_CODE
        mov word [edi+4], 0x8E00
        shr eax, 16
        mov [edi+6], ax
        add edi, 8
        inc ecx
        cmp ecx, 32
        jb .idt
        mov edi, IDT_BASE + RET_VEC * 8
        mov eax, ret_trap
        mov [edi], ax
        mov word [edi+2], SEL_CODE
        mov word [edi+4], 0xEE00
        shr eax, 16
        mov [edi+6], ax
        mov edi, IDT_BASE + TRAP_VEC * 8
        mov eax, if_probe
        mov [edi], ax
        mov word [edi+2], SEL_CODE
        mov word [edi+4], 0x8F00
        shr eax, 16
        mov [edi+6], ax
        mov edi, IDT_BASE + INTR_VEC * 8
        mov eax, if_probe
        mov [edi], ax
        mov word [edi+2], SEL_CODE
        mov word [edi+4], 0x8E00
        shr eax, 16
        mov [edi+6], ax
        lidt [idtr]
        mov dword [TSS_BASE + 4], STACK0T
        mov dword [TSS_BASE + 8], SEL_DATA
        mov word [TSS_BASE + 0x66], 0x68
        mov ax, SEL_TSS
        ltr ax
        mov dword [0x30000], 0x11223344
        mov dword [0x30004], 0x55667788
        mov dword [0x30020], 5
        mov dword [0x32000], 0x99AABBCC
        mov dword [0x34010], 0xDEADBEEF
        mov dword [0x36010], 0xFEEDFACE
        mov dword [0x30FFC], 0xAAAAAAAA     ; a CMPXCHG8B across into a read-only page
        mov dword [0x31000], 0xBBBBBBBB
        mov dword [0x400000], 0             ; (as a page table, with PSE off: nothing present)
        mov dword [0x400010], 0xCAFEBABE    ; in the 4 MB page at 400000
        mov dword [0x5FF000], 0x13579BDF
        mov edi, PD
        mov ecx, 1024
        xor eax, eax
        rep stosd
        mov dword [PD + 0], PT0 | 7
        mov dword [PD + 4], PT1 | 7
        mov edi, PT0
        mov eax, 7
        mov ecx, 1024
.pt0:   stosd
        add eax, 0x1000
        loop .pt0
        mov dword [PT0 + 0x32 * 4], 0x32000 | 5    ; user, read-only
        mov dword [PT0 + 0x31 * 4], 0x31000 | 5    ; user, read-only
        mov dword [PD + 8], 0x400000 | 0x87        ; linear 800000: a 4 MB page, user r/w (PS)
        mov dword [PD + 12], 0x400000 | 0x83       ; linear C00000: the same, supervisor
        mov edi, PT1
        mov ecx, 1024
        xor eax, eax
        rep stosd
        mov dword [PT1 + 0], 0x34000 | 7           ; linear 400000 -> 34000
        mov eax, PD
        mov cr3, eax
        mov eax, cr0
        or eax, 0x80000000
        mov cr0, eax
        jmp .paged
.paged:
        mov esi, msg_start
        call puts

        ; ---- CPUID
        mov byte [tno], 1
        mov eax, 1
        cpuid
        call ok_eax
        mov byte [tno], 2
        mov eax, 1
        cpuid
        mov eax, edx
        call ok_eax
        mov byte [tno], 3
        mov eax, 1
        cpuid
        mov eax, ebx
        and eax, 0xFF00                     ; the CLFLUSH line, in 8-byte units
        call ok_eax
        mov byte [tno], 4
        mov eax, 2
        cpuid
        call ok_eax
        mov byte [tno], 5
        mov eax, 2
        cpuid
        mov eax, edx
        call ok_eax

        mov eax, cr4
        or eax, 0x600
        mov cr4, eax
        mov dword [qno], 0
        mov dword [cur_mx], 0x1F80
        mov esi, main_stubs
        call run_table
        mov esi, rc_stubs
        mov dword [cur_mx], 0x3F80
        call run_table
        mov dword [cur_mx], 0x5F80
        mov esi, rc_stubs
        call run_table
        mov dword [cur_mx], 0x7F80
        mov esi, rc_stubs
        call run_table
        mov dword [cur_mx], 0x9F80
        mov esi, rc_stubs
        call run_table
        mov dword [cur_mx], 0x1FC0          ; DAZ
        mov esi, rc_stubs
        call run_table
        mov esi, main_stubs                 ; and every one under DAZ
        call run_table
        mov dword [cur_mx], 0x1F80
        mov esi, int_stubs
        call run_table

        ; ---- by hand
        mov byte [tno], 0x40
        mov dword [resume], .t41
        clflush [pairs]
        mov eax, 1
        call ok_eax
.t41:   mov byte [tno], 0x41
        mov dword [resume], .t42
        clflush [0x1000000]                 ; not present: #PF
        call ok_eax
.t42:   mov byte [tno], 0x42
        mov dword [resume], .t43
        lfence
        mfence
        pause
        mov eax, 2
        call ok_eax
.t43:   mov byte [tno], 0x43                ; the MXCSR mask: FXSAVE's
        mov dword [resume], .t44
        fxsave [fxarea]
        mov eax, [fxarea + 28]
        call ok_eax
.t44:   mov byte [tno], 0x44                ; DAZ: a reserved bit (#GP) or not
        mov dword [resume], .t45
        mov dword [tmpi], 0x1FC0
        ldmxcsr [tmpi]
        stmxcsr [tmpi]
        mov eax, [tmpi]
        call ok_eax
.t45:   mov dword [tmpi], 0x1F80
        ldmxcsr [tmpi]
        mov byte [tno], 0x45
        mov dword [resume], .t46
        db 0xF3, 0x0F, 0xFC, 0xC1           ; F3 on PADDB: reserved
        call ok_eax
.t46:   mov byte [tno], 0x46
        mov dword [resume], .t47
        mov eax, cr4
        and eax, ~0x200
        mov cr4, eax
        paddb xmm0, xmm1                    ; OSFXSR clear: #UD
        call ok_eax
.t47:   mov eax, cr4
        or eax, 0x200
        mov cr4, eax
        mov byte [tno], 0x47
        mov dword [resume], .t48
        movdqa xmm0, [pairs + 8]            ; #GP
        call ok_eax
.t48:   mov byte [tno], 0x48
        mov dword [resume], .t49
        paddb xmm0, [pairs + 8]             ; #GP
        call ok_eax
.t49:   mov byte [tno], 0x49
        mov dword [resume], .t4a
        mov dword [tmpi], 0x1D80            ; ZE unmasked
        ldmxcsr [tmpi]
        movapd xmm0, [pairs]
        xorpd xmm1, xmm1
        divpd xmm0, xmm1                    ; #XM
        call ok_eax
.t4a:   mov dword [tmpi], 0x1F80
        ldmxcsr [tmpi]
        jmp t60_done

run_table:                                  ; ESI: stubs; each over each pair
.op:    mov ebx, [esi]
        test ebx, ebx
        jz .d
        mov edi, pairs
        mov ecx, NPAIRS
.pair:  movaps xmm0, [edi]
        movaps xmm1, [edi + 16]
        ldmxcsr [cur_mx]
        push edi
        push ecx
        call ebx
        pop ecx
        pop edi
        call pr_x0
        add edi, 32
        loop .pair
        add esi, 4
        jmp .op
.d:     ret
t60_done:
.t60:   xor eax, eax
        mov cr4, eax
        mov esi, msg_done
        call puts
        mov al, 0
        out 0xF4, al
.h:     hlt
        jmp .h
ring3:
        mov [saved_esp], esp
        mov dword [resume], .back
        mov ax, SEL_DATA3
        mov ds, ax
        mov es, ax
        push dword SEL_DATA3
        push dword STACK3
        push dword [r3flags]
        push dword SEL_CODE3
        push ebx
        iretd
.back:  ret

pr_x0:                                      ; "X<n> " lanes 3..0, MXCSR; then MXCSR back to cur_mx
        pushad
        movups [tmpx], xmm0
        stmxcsr [tmpm]
        mov esi, msg_x
        call puts
        mov eax, [qno]
        call hex16
        mov ebx, 12
.l:     mov al, ' '
        out 0xE9, al
        mov eax, [tmpx + ebx]
        call hex32
        sub ebx, 4
        jns .l
        mov al, ' '
        out 0xE9, al
        mov eax, [tmpm]
        call hex32
        mov al, 10
        out 0xE9, al
        ldmxcsr [cur_mx]
        inc dword [qno]
        popad
        ret
pr_mm0:
        pushad
        movq [tmpq], mm0
        mov esi, msg_q
        call puts
        mov eax, [qno]
        call hex16
        mov al, ' '
        out 0xE9, al
        mov eax, [tmpq + 4]
        call hex32
        mov eax, [tmpq]
        call hex32
        mov al, 10
        out 0xE9, al
        inc dword [qno]
        popad
        ret
